-- Phase B: administrative units of Hưng Yên after the 2025 merger (Nghị quyết 1666/NQ-UBTVQH15).
-- 104 commune-level units: 93 Xã + 11 Phường, province code 33.
-- Dataset: apps/api/data/hung-yen-wards.json (dataset_version hy-2025-nq1666-qd19-2026-11-17).
-- Source: diachiviet.com open data (CC BY 4.0), cross-checked against the resolution text.

CREATE TABLE wards (
  code text PRIMARY KEY,
  province_code text NOT NULL,
  name text NOT NULL,
  type text NOT NULL CHECK (type IN ('Xã','Phường')),
  search_text text NOT NULL,
  in_service_area boolean NOT NULL DEFAULT true,
  dataset_version text NOT NULL,
  source text NOT NULL,
  source_checked_at date NOT NULL,
  disabled_at timestamptz,
  disabled_by uuid REFERENCES users(id),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX wards_search_idx ON wards (search_text text_pattern_ops);
CREATE INDEX wards_province_idx ON wards (province_code);

-- dataset_version / source / source_checked_at come from apps/api/data/hung-yen-wards.json meta.
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, search_text = EXCLUDED.search_text;

-- Addresses: canonical province/ward codes. Legacy columns stay for history rendering.
ALTER TABLE addresses
  ADD COLUMN province_code text,
  ADD COLUMN ward_code text REFERENCES wards(code),
  ADD COLUMN needs_confirmation boolean NOT NULL DEFAULT false;
ALTER TABLE addresses ALTER COLUMN district DROP NOT NULL;

-- Every pre-existing address was typed by hand and must be re-picked from the ward list.
UPDATE addresses SET needs_confirmation = true WHERE ward_code IS NULL;
CREATE INDEX addresses_ward_idx ON addresses (ward_code);

